<?php defined('_JEXEC') or die; ?><div class="container-fluid"><h1>Tour and holiday packages</h1><div class="table-responsive"><table class="table table-striped"><thead><tr><th>Title</th><th>Duration</th><th>Mode</th><th>Capacity</th><th>Price</th><th>State</th></tr></thead><tbody><?php foreach($this->items as $item): ?><tr><td><?php echo htmlspecialchars($item['title'],ENT_QUOTES,'UTF-8'); ?></td><td><?php echo (int)$item['duration_days']; ?> days / <?php echo (int)$item['duration_nights']; ?> nights</td><td><?php echo htmlspecialchars($item['booking_mode'],ENT_QUOTES,'UTF-8'); ?></td><td><?php echo (int)$item['capacity']; ?></td><td><?php echo htmlspecialchars($item['currency'].' '.number_format((float)$item['base_price'],2),ENT_QUOTES,'UTF-8'); ?></td><td><?php echo (int)$item['state']===1?'Published':'Unpublished'; ?></td></tr><?php endforeach; ?><?php if(!$this->items): ?><tr><td colspan="6">No packages have been added.</td></tr><?php endif; ?></tbody></table></div></div>
